function prepareUmamiScope({ apiBaseUrl, websiteId, blog, timeZone }, anchor) {
  if (typeof apiBaseUrl !== "string")
    throw new Error("Configure the canonical HTTPS API base of your self-hosted Umami instance.");
  const base = apiBaseUrl.trim().replace(/\/+$/u, "");
  const match = /^https:\/\/([^/?#\s]+)(\/[^?#\s]*)$/u.exec(base);
  if (!match || match[1].includes("@"))
    throw new Error("Use a canonical HTTPS Umami API base without credentials, query or fragment.");
  const authority = /^([^:]+)(?::([0-9]+))?$/u.exec(match[1]);
  if (
    !authority ||
    authority[1].length > 253 ||
    authority[1]
      .split(".")
      .some((part) => !/^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/u.test(part))
  )
    throw new Error("The Umami API hostname is invalid.");
  if (authority[2] && (Number(authority[2]) < 1 || Number(authority[2]) > 65535))
    throw new Error("The Umami API port is invalid.");
  if (
    !match[2].endsWith("/api") ||
    match[2]
      .split("/")
      .slice(1)
      .some((part) => !/^[A-Za-z0-9._~-]+$/u.test(part) || part === "." || part === "..")
  )
    throw new Error("Use the self-hosted API base ending in /api.");
  if (
    typeof websiteId !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu.test(websiteId.trim()) ||
    /^0{8}-0{4}-0{4}-0{4}-0{12}$/u.test(websiteId.trim())
  )
    throw new Error("Configure the Umami website UUID.");
  if (typeof blog !== "string" || !blog.trim()) throw new Error("Configure a site label.");
  if (typeof timeZone !== "string" || !timeZone.trim())
    throw new Error("Configure an IANA processing timezone.");
  const timezone = timeZone.trim(),
    date = new Date(anchor),
    endAt = date.getTime(),
    week = 7 * 24 * 60 * 60 * 1000;
  if (!Number.isSafeInteger(endAt) || endAt < week * 2)
    throw new Error("The captured report time is invalid.");
  let parts;
  try {
    parts = Object.fromEntries(
      new Intl.DateTimeFormat("en", {
        timeZone: timezone,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      })
        .formatToParts(date)
        .map((part) => [part.type, part.value]),
    );
  } catch {
    throw new Error("The processing timezone is invalid.");
  }
  const id = websiteId.trim().toLowerCase(),
    endpoint = base + "/websites/" + id;
  return {
    apiBaseUrl: base,
    websiteId: id,
    blog: blog.trim(),
    timeZone: timezone,
    anchor: date.toISOString(),
    reportDate: parts.year + "-" + parts.month + "-" + parts.day,
    startAt: endAt - week,
    endAt,
    previousStartAt: endAt - week * 2,
    previousEndAt: endAt - week,
    statsUrl: endpoint + "/stats",
    metricsUrl: endpoint + "/metrics",
  };
}

const prepareClockScope = function prepareScope(input) {
  return prepareUmamiScope(input, new Date().toISOString());
};

return [
  {
    json: prepareUmamiScope(
      {
        apiBaseUrl: "https://YOUR_UMAMI_HOST/api",
        websiteId: "YOUR_UMAMI_WEBSITE_UUID",
        blog: "Example site",
        timeZone: "UTC",
      },
      $now.toISO(),
    ),
    pairedItem: { item: 0 },
  },
];

const prepare = function prepareUmamiSummary({
  body,
  statusCode,
  blog,
  anchor,
  timeZone,
  startAt,
  endAt,
}) {
  if (statusCode !== 200 || !body || typeof body !== "object" || Array.isArray(body))
    throw new Error("Umami did not return website summary statistics.");
  const names = ["pageviews", "visitors", "visits", "bounces", "totaltime"];
  const comparison = body.comparison;
  if (!comparison || typeof comparison !== "object" || Array.isArray(comparison))
    throw new Error("Umami 3.4.1 statistics must include the comparison object.");
  for (const metrics of [body, comparison])
    for (const name of names)
      if (typeof metrics[name] !== "number" || !Number.isFinite(metrics[name]) || metrics[name] < 0)
        throw new Error("Invalid Umami statistic: " + name);
  const statistics = Object.fromEntries(names.map((name) => [name, body[name]])),
    previous = Object.fromEntries(names.map((name) => [name, comparison[name]]));
  const data = {
    site: blog,
    capturedAt: anchor,
    timezone: timeZone,
    period: { startAt, endAt, kind: "rolling seven days; inclusive API timestamp bounds" },
    statistics,
    comparison: previous,
    definitions: {
      pageviews: "pageview count",
      visitors: "unique visitor count",
      visits: "visit count",
      bounces: "single-page visits without a custom event",
      totaltime: "total visit duration in seconds",
    },
  };
  return { statistics, comparison: previous, summaryData: JSON.stringify(data) };
};

const response = $input.first().json,
  scope = $("Prepare Report Scope").first().json;
return [
  {
    json: prepare({ body: response.body, statusCode: response.statusCode, ...scope }),
    pairedItem: { item: 0 },
  },
];

const response = $input.first().json;
const text = response.body?.choices?.[0]?.message?.content;
if (response.statusCode !== 200 || typeof text !== "string" || !text.trim())
  throw new Error("The analysis did not return nonempty text.");
return [{ json: { summary: text }, pairedItem: { item: 0 } }];

const prepare = function prepareUmamiPages({
  currentBody,
  currentStatus,
  previousBody,
  previousStatus,
  blog,
  timeZone,
  startAt,
  endAt,
  previousStartAt,
  previousEndAt,
}) {
  if (
    currentStatus !== 200 ||
    previousStatus !== 200 ||
    !Array.isArray(currentBody) ||
    !Array.isArray(previousBody)
  )
    throw new Error("Umami did not return both ranked page lists.");
  const validate = (rows) => {
    for (const row of rows)
      if (
        !row ||
        typeof row !== "object" ||
        Array.isArray(row) ||
        (row.x !== null && typeof row.x !== "string") ||
        typeof row.y !== "number" ||
        !Number.isFinite(row.y) ||
        row.y < 0
      )
        throw new Error("Invalid Umami ranked page row.");
    return rows;
  };
  const current = validate(currentBody),
    previous = validate(previousBody);
  return {
    currentPages: current,
    previousPages: previous,
    pageData: JSON.stringify({
      site: blog,
      timezone: timeZone,
      metric:
        "Unique visitors by page path in the audited Umami 3.4.1 /metrics?type=path implementation; x is the page path, y the count. A null path is an unspecified dimension, not an invented URL.",
      scope:
        "One ranked response per range, service default at most 500 rows; no pagination. Absence from a ranked response does not establish zero traffic.",
      current: { startAt, endAt, rows: current },
      previous: { startAt: previousStartAt, endAt: previousEndAt, rows: previous },
    }),
  };
};

const previous = $input.first().json,
  current = $("Read Current Page Visitors").first().json,
  scope = $("Prepare Report Scope").first().json;
return [
  {
    json: prepare({
      currentBody: current.body,
      currentStatus: current.statusCode,
      previousBody: previous.body,
      previousStatus: previous.statusCode,
      ...scope,
    }),
    pairedItem: { item: 0 },
  },
];

const prepare = function prepareUmamiRow({ summary, pagesReport, reportDate, blog }) {
  for (const [name, value] of Object.entries({ summary, pagesReport }))
    if (typeof value !== "string" || !value.trim())
      throw new Error("The " + name + " analysis did not return nonempty text.");
  if (!/^\d{4}-\d{2}-\d{2}$/u.test(reportDate) || typeof blog !== "string" || !blog.trim())
    throw new Error("The report date or site label is invalid.");
  return {
    row: { Date: reportDate, Summary: summary, "Top pages": pagesReport, "Blog name": blog },
  };
};

const response = $input.first().json;
const text = response.body?.choices?.[0]?.message?.content;
if (response.statusCode !== 200 || typeof text !== "string" || !text.trim())
  throw new Error("The analysis did not return nonempty text.");
const scope = $("Prepare Report Scope").first().json;
return [
  {
    json: prepare({
      summary: $("Check Traffic Summary").first().json.summary,
      pagesReport: text,
      reportDate: scope.reportDate,
      blog: scope.blog,
    }).row,
    pairedItem: { item: 0 },
  },
];

const confirm = function confirmUmamiReport({ row }) {
  if (
    !row ||
    typeof row !== "object" ||
    Array.isArray(row) ||
    !Number.isInteger(row.id) ||
    row.id <= 0
  )
    throw new Error("Baserow did not confirm a created report row ID.");
  return { row };
};

return [{ json: confirm({ row: $input.first().json }).row, pairedItem: { item: 0 } }];
